class HeadWiseLinear(nn.Module):
    """
    一个 head-wise 的线性层。
    输入 shape: [..., heads, in_features]
    输出 shape: [..., heads, out_features]
    """
    def __init__(self, num_heads, in_features, out_features, bias=True):
        super().__init__()
        self.num_heads = num_heads
        self.in_features = in_features
        self.out_features = out_features

        self.weight = nn.Parameter(torch.empty(num_heads, in_features, out_features))
        if bias:
            self.bias = nn.Parameter(torch.empty(num_heads, out_features))
        else:
            self.register_parameter('bias', None)
        
    #     self.reset_parameters()

    # def reset_parameters(self):
    # # Kaiming Uniform 初始化
    # self.weight.normal_(mean=0.0, std=std) 
    #     nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
    #     if self.bias is not None:
    #         fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
    #         # fan_in is an integer, so we use it directly
    #         bound = 1 / math.sqrt(fan_in) # The fix is here: removed [0]
    #         nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        # x: [bsz, length, heads, in_features]
        # weight: [heads, in_features, out_features] -> hio
        # bias: [heads, out_features] -> ho
        # 我们期望输出: [bsz, length, heads, out_features]
        # einsum a,b->ab, c->c
        # 'blhi,hio->blho'
        out = torch.einsum('...hi,hio->...ho', x, self.weight)
        if self.bias is not None:
            out = out + self.bias
        return out

    def extra_repr(self):
        return f'num_heads={self.num_heads}, in_features={self.in_features}, out_features={self.out_features}, bias={self.bias is not None}'

class SelectionModel(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.head_dim = config.hidden_size // config.num_attention_heads
        self.num_key_value_heads = config.num_key_value_heads
        
        # 特征维度计算
        # 注意力特征的维度，假设它已经被处理成 per-head 的形式
        # 您代码中是 num_key_value_groups * 8，我们直接使用它
        attn_feature_dim = config.num_attention_heads // config.num_key_value_heads * 8
        kv_norm_dim = 2 # key_norm, value_norm
        
        # 1. KV 预处理器
        kv_input_dim = self.head_dim * 2
        kv_embed_dim = 16
        # self.kv_projector = HeadWiseLinear(self.num_key_value_heads, kv_input_dim, kv_embed_dim)

        # 2. 特征归一化层
        # LayerNorm 在最后一个维度上操作，所以可以安全地用于 head-wise 的数据
        total_feature_dim = kv_input_dim + attn_feature_dim
        self.feature_norm = nn.LayerNorm(total_feature_dim)
        
        # 3. 核心MLP，由头独立的线性层构成
        hidden_dim = 16
        self.fc1 = HeadWiseLinear(self.num_key_value_heads, total_feature_dim, hidden_dim)
        self.activation = nn.GELU()
        self.fc2 = HeadWiseLinear(self.num_key_value_heads, hidden_dim, 1)

    def forward(self, key, value, attn_info):
        # 输入 shape 假设为: [bsz, heads, length, head_dim]
        # 为了方便处理，我们统一将 length 维度放在前面
        key = key.transpose(1, 2)    # -> [bsz, length, heads, head_dim]
        value = value.transpose(1, 2)  # -> [bsz, length, heads, head_dim]
        attn_info = attn_info.transpose(1, 2) # -> [bsz, length, heads, attn_feature_dim]

        # # 计算内在特征
        # key_norm = key.norm(dim=-1, keepdim=True)
        # value_norm = value.norm(dim=-1, keepdim=True)
        
        # 1. KV预处理
        kv_concat = torch.cat([key, value], dim=-1)
        # kv_embed = self.kv_projector(kv_concat) # -> [bsz, length, heads, kv_embed_dim]

        # 2. 拼接所有特征
        feature_vector = torch.cat(
            [
                kv_concat,
                attn_info,
            ],
            dim=-1,
        ) # -> [bsz, length, heads, total_feature_dim]

        # 3. 特征归一化 (在特征维度上)
        # normalized_features = self.feature_norm(feature_vector)
        
        # 4. 通过头独立的MLP得到分数
        h = self.fc1(feature_vector)
        h = self.activation(h)
        out = self.fc2(h) # -> [bsz, length, heads, 1]

        return out


class Qwen2Attention(nn.Module):
    """Multi-headed attention from 'Attention Is All You Need' paper"""

    def __init__(self, config: Qwen2Config, layer_idx: int):
        super().__init__()
        self.config = config
        self.layer_idx = layer_idx
        self.head_dim = getattr(config, "head_dim", config.hidden_size // config.num_attention_heads)
        self.num_key_value_groups = config.num_attention_heads // config.num_key_value_heads
        self.scaling = self.head_dim**-0.5
        self.attention_dropout = config.attention_dropout
        self.is_causal = True
        self.q_proj = nn.Linear(config.hidden_size, config.num_attention_heads * self.head_dim, bias=True)
        self.k_proj = nn.Linear(config.hidden_size, config.num_key_value_heads * self.head_dim, bias=True)
        self.v_proj = nn.Linear(config.hidden_size, config.num_key_value_heads * self.head_dim, bias=True)
        self.o_proj = nn.Linear(config.num_attention_heads * self.head_dim, config.hidden_size, bias=False)
        self.judge_model = SelectionModel(config)
        self.reference = SelectionModel(config)
        self.sliding_window = config.sliding_window
        if not (
            self.config.use_sliding_window
            and getattr(self.config, "sliding_window", None) is not None
            and self.layer_idx >= self.config.max_window_layers
        ):
            self.sliding_window = None
        self.num_attention_heads = config.num_attention_heads
        self.initial_chunk = 1024
        self.step_size = 256
    def init_cache(self, q, k, v, layer_idx):
        pass
    def init_chunk(self, initial_chunk, step_size):
        self.initial_chunk = initial_chunk
        self.step_size = step_size

    def cache_process(self, q, k, v, cache_current, topk, reference=False):
        return k, v, cache_current, None
    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: Tuple[torch.Tensor, torch.Tensor],
        attention_mask: Optional[torch.Tensor],
        past_key_value: Optional[Cache] = None,
        cache_position: Optional[torch.LongTensor] = None,
        cache_drop: Optional[list] = None,
        reference: Optional[bool] = False,
        disable_eviction: Optional[bool] = False,
        **kwargs: Unpack[FlashAttentionKwargs],
    ) -> Tuple[torch.Tensor, Optional[torch.Tensor], Optional[Tuple[torch.Tensor]]]:
        input_shape = hidden_states.shape[:-1]
        batch_size, seq_len, _ = hidden_states.size()
        hidden_shape = (*input_shape, -1, self.head_dim)

        query_states = self.q_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        key_states = self.k_proj(hidden_states).view(hidden_shape).transpose(1, 2)
        value_states = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)

        cos, sin = position_embeddings
        query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)

        attention_interface: Callable = eager_attention_forward
        if self.config._attn_implementation != "eager":
            if self.config._attn_implementation == "sdpa" and kwargs.get("output_attentions", False):
                logger.warning_once(
                    "`torch.nn.functional.scaled_dot_product_attention` does not support `output_attentions=True`. Falling back to "
                    'eager attention. This warning can be removed using the argument `attn_implementation="eager"` when loading the model.'
                )
            else:
                attention_interface = ALL_ATTENTION_FUNCTIONS[self.config._attn_implementation]

        cache_current = cache_drop[self.layer_idx] if cache_drop is not None else None
        if seq_len <= self.initial_chunk:
            # 一次性投影全部
            
            # 如果传入了 past_key_value，就更新，但在纯从头 batch 的场景下通常是 None
            if past_key_value is not None:
                cache_kwargs = {"sin": sin, "cos": cos, "cache_position": cache_position}
                key_states, value_states = past_key_value.update(key_states, value_states, self.layer_idx, cache_kwargs)

            # Attentio
            attn_output, attn_weights = attention_interface(
                self,
                query_states,
                key_states,
                value_states,
                attention_mask,
                dropout=0.0 if not self.training else self.attention_dropout,
                scaling=self.scaling,
                sliding_window=self.sliding_window,
                **kwargs,
            )
            # 拼回原始维度并做 o_proj
            attn_output = attn_output.reshape(batch_size, seq_len, -1).contiguous()
            attn_output = self.o_proj(attn_output)

            # 直接将当前 key_states, value_states 作为新的 KV 缓存返回
            return attn_output, None, None

        # --- 否则，序列长度 > initial_chunk，需要拆块累积计算 ---
        outputs_chunks = []  # 用于收集各块的 attention 输出

        # 1. 处理第一块 [0:initial_chunk)
        # print(self.initial_chunk)
        first_end = self.initial_chunk

        q_first = query_states[:,:,:first_end]
        k_first = key_states[:,:,:first_end]
        v_first = value_states[:,:,:first_end]

        # 累积 KV
        accum_k = k_first  # [B, n_kv_head, L_acc, head_dim]
        accum_v = v_first  # [B, n_kv_head, L_acc, head_dim]
        # print(attention_mask.shape)
        # Attention Mask 切片 (如果提供了 mask)
        if attention_mask is not None:
            # 假设 attention_mask 形状是 [B, 1, total_Q, total_K]，第一块 Q 和 K 都是 [0:first_end)
            mask_first = attention_mask[:, :, :first_end, :first_end]
        else:
            mask_first = None

        out_first, attn_weights = attention_interface(
            self,
            q_first,
            accum_k,
            accum_v,
            mask_first,
            dropout=0.0 if not self.training else self.attention_dropout,
            scaling=self.scaling,
            **kwargs,
        )
        # [B, n_head, L1, head_dim] -> [B, L1, n_head*head_dim]
        out_first = out_first.reshape(batch_size, first_end, -1).contiguous()
        outputs_chunks.append(out_first)  # 暂时收集未经 o_proj 的原始拼接形状
        self.init_cache(q_first, accum_k, accum_v, self.layer_idx)
        # 2. 处理后续每 64 token 一块
        #    块 i 的范围 [start: end)，其中 start = 1024 + m*64, end = min(start+64, seq_len)
        cur_start = first_end
        idx = 0
        cache_index_list = []
        # critic_scores = []
        while cur_start < seq_len:
            cur_end = min(cur_start + self.step_size, seq_len)
            cur_len = cur_end - cur_start

            q_c = query_states[:,:,cur_start:cur_end]
            k_c = key_states[:,:,cur_start:cur_end]
            v_c = value_states[:,:,cur_start:cur_end]
        
            # 将本块 k_c, v_c 追加到累积缓存 (dim=2 为序列维度)
            accum_k = torch.cat([accum_k, k_c], dim=2)  # [B, n_kv_head, L_acc+Lc, head_dim]
            accum_v = torch.cat([accum_v, v_c], dim=2)  # [B, n_kv_head, L_acc+Lc, head_dim]
            # print(accum_v.shape)
            critic_scores=None
            # if cur_start + 2* self.step_size<=seq_len:
            #     critic_scores = self.critic_model(accum_k, accum_v, q_c[:,:,cur_end:(seq_len//self.step_size)*self.step_size])
                # critic_scores.append(scores)
            # 构造本块的 attention_mask：queries=[cur_start:cur_end), keys=[0:cur_end)
            if attention_mask is not None:
                mask_chunk = attention_mask[:, :, cur_start:cur_end, :cur_end]
            else:
                mask_chunk = None

            out_c, _ = attention_interface(
                self,
                q_c,
                accum_k,
                accum_v,
                mask_chunk,
                dropout=0.0 if not self.training else self.attention_dropout,
                scaling=self.scaling,
                **kwargs,
            )
            # [B, n_head, Lc, head_dim] -> [B, Lc, n_head*head_dim]
            out_c = out_c.reshape(batch_size, cur_len, -1).contiguous()
            outputs_chunks.append(out_c)
            if cur_end<cur_start + self.step_size:
                break

            if not disable_eviction:
                if cache_current is None:
                    accum_k, accum_v, cache_index, score = self.cache_process(
                        q_c, accum_k, accum_v, None, topk=False, reference=reference
                    )
                
                    cache_index_list.append([cache_index, score, critic_scores])
                elif cache_current.shape[0] > idx:
                    cache_d = cache_current[idx] if cache_current is not None else None
                    accum_k, accum_v, cache_index, score = self.cache_process(
                        q_c, accum_k, accum_v, cache_d, topk=False, reference=reference
                    )
                
                    cache_index_list.append([cache_index, score, critic_scores])
            
            idx += 1
            # print(cur_start, idx, accum_k.shape)
            # 更新下一个块的起始位置
            cur_start = cur_end

        # 3. 把所有块输出拼接成 [B, seq_len, n_head*head_dim]，再做一次 o_proj 得到最终输出
        concatenated = torch.cat(outputs_chunks, dim=1)  # [B, seq_len, n_head*head_dim]
        hidden_output = self.o_proj(concatenated)       # [B, seq_len, hidden_size]

        return hidden_output, cache_index_list, concatenated.reshape(
            concatenated.shape[0], concatenated.shape[1], self.num_attention_heads, -1
        )



class Qwen2RMSNorm(nn.Module):
    def __init__(self, hidden_size, eps=1e-6):
        """
        Qwen2RMSNorm is equivalent to T5LayerNorm
        """
        super().__init__()
        self.weight = nn.Parameter(torch.ones(hidden_size))
        self.variance_epsilon = eps

    def forward(self, hidden_states):
        input_dtype = hidden_states.dtype
        hidden_states = hidden_states.to(torch.float32)
        variance = hidden_states.pow(2).mean(-1, keepdim=True)
        hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon)
        return self.weight * hidden_states.to(input_dtype)

    def extra_repr(self):
        return f"{tuple(self.weight.shape)}, eps={self.variance_epsilon}"


class Qwen2DecoderLayer(nn.Module):
    def __init__(self, config: Qwen2Config, layer_idx: int):
        super().__init__()
        self.hidden_size = config.hidden_size
        self.self_attn = Qwen2Attention(config=config, layer_idx=layer_idx)
        self.mlp = Qwen2MLP(config)
        self.input_layernorm = Qwen2RMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.post_attention_layernorm = Qwen2RMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        if config.sliding_window and config._attn_implementation != "flash_attention_2":
            logger.warning_once(
                f"Sliding Window Attention is enabled but not implemented for `{config._attn_implementation}`; "
                "unexpected results may be encountered."
            )

    def forward(
        self,
        hidden_states: torch.Tensor,
        attention_mask: Optional[torch.Tensor] = None,
        position_ids: Optional[torch.LongTensor] = None,
        past_key_value: Optional[Cache] = None,
        output_attentions: Optional[bool] = False,
        use_cache: Optional[bool] = False,
        cache_position: Optional[torch.LongTensor] = None,
        position_embeddings: Optional[Tuple[torch.Tensor, torch.Tensor]] = None,  # necessary, but kept here for BC
        cache_drop: Optional[list] = None,
        reference: Optional[bool] = False,
        disable_eviction: Optional[bool] = False,
        **kwargs: Unpack[FlashAttentionKwargs],
    ) -> Tuple[torch.FloatTensor, Optional[Tuple[torch.FloatTensor, torch.FloatTensor]]]:
        residual = hidden_states

        hidden_states = self.input_layernorm(hidden_states)

        # Self Attention
        hidden_states, cache_index, head_wise_info = self.self_attn(
            hidden_states=hidden_states,
            attention_mask=attention_mask,
            position_ids=position_ids,
            past_key_value=past_key_value,
            output_attentions=output_attentions,
            use_cache=use_cache,
            cache_position=cache_position,
            position_embeddings=position_embeddings,
            cache_drop=cache_drop,
            reference=reference,
            disable_eviction=disable_eviction,
            **kwargs,
        )
        hidden_states = residual + hidden_states

        # Fully Connected
        residual = hidden_states
        hidden_states = self.post_attention_layernorm(hidden_states)
        hidden_states = self.mlp(hidden_states)
        hidden_states = residual + hidden_states

        outputs = (hidden_states,)
        if output_attentions:
            outputs += (cache_index,)
        outputs += (head_wise_info,)
        return outputs


class Qwen2RotaryEmbedding(nn.Module):
    def __init__(self, config: Qwen2Config, device=None):
        super().__init__()
        # BC: "rope_type" was originally "type"
        if hasattr(config, "rope_scaling") and config.rope_scaling is not None:
            self.rope_type = config.rope_scaling.get("rope_type", config.rope_scaling.get("type"))
        else:
            self.rope_type = "default"
        self.max_seq_len_cached = config.max_position_embeddings
        self.original_max_seq_len = config.max_position_embeddings

        self.config = config
        self.rope_init_fn = ROPE_INIT_FUNCTIONS[self.rope_type]

        inv_freq, self.attention_scaling = self.rope_init_fn(self.config, device)
        self.register_buffer("inv_freq", inv_freq, persistent=False)
        self.original_inv_freq = self.inv_freq

    @torch.no_grad()
    @dynamic_rope_update  # power user: used with advanced RoPE types (e.g. dynamic rope)
    def forward(self, x, position_ids):
        inv_freq_expanded = self.inv_freq[None, :, None].float().expand(position_ids.shape[0], -1, 1).to(x.device)
        position_ids_expanded = position_ids[:, None, :].float()

        device_type = x.device.type if isinstance(x.device.type, str) and x.device.type != "mps" else "cpu"
        with torch.autocast(device_type=device_type, enabled=False):  # Force float32
            freqs = (inv_freq_expanded.float() @ position_ids_expanded.float()).transpose(1, 2)
            emb = torch.cat((freqs, freqs), dim=-1)
            cos = emb.cos() * self.attention_scaling
            sin = emb.sin() * self.attention_scaling

        return cos.to(dtype=x.dtype), sin.to(dtype=x.dtype)


